class Solution {
    public String convert(String s, int numRows) {
        int n = s.length();
        if (numRows == 1) return s;                 // 边界：一行就是原串
        char[][] mat = new char[numRows][n];        // 列数取最坏 n，简单粗暴
        for (int i = 0; i < numRows; i++)
            for (int j = 0; j < n; j++) mat[i][j] = '#'; // 占位符

        int row = 0, col = 0, dir = 1;
        for (int k = 0; k < n; k++) {
            mat[row][col] = s.charAt(k);
            if (row == 0) dir = 1;                  // 到顶，改为向下
            else if (row == numRows - 1) dir = -1;  // 到底，改为向上
            row += dir;
            if (dir == 1) col++;                    // 向下时列才 +1（斜向共享列号）
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < numRows; i++)
            for (int j = 0; j < n; j++)
                if (mat[i][j] != '#') sb.append(mat[i][j]);
        return sb.toString();
    }
}

class Solution {
    public String convert(String s, int numRows) {
        if (numRows == 1) return s;
        StringBuilder[] rows = new StringBuilder[numRows];
        for (int i = 0; i < numRows; i++) rows[i] = new StringBuilder();
        int row = 0, dir = 1;
        for (int k = 0; k < s.length(); k++) {
            rows[row].append(s.charAt(k));
            if (row == 0) dir = 1;
            else if (row == numRows - 1) dir = -1;
            row += dir;
        }
        StringBuilder res = new StringBuilder();
        for (StringBuilder r : rows) res.append(r);
        return res.toString();
    }
}

class Solution {
    public String convert(String s, int numRows) {
        if (numRows == 1) return s;
        int n = s.length();
        int T = 2 * numRows - 2;                    // 一个完整周期的长度
        StringBuilder res = new StringBuilder();
        for (int r = 0; r < numRows; r++) {
            for (int i = r; i < n; ) {
                res.append(s.charAt(i));           // 竖直列（含首行/末行）
                // 非首尾行才有斜向字符：下标为 i + (T - 2r)
                if (r > 0 && r < numRows - 1) {
                    int diag = i + (T - 2 * r);
                    if (diag < n) res.append(s.charAt(diag));
                }
                i += T;                             // 跳到下一个周期的同列位置
            }
        }
        return res.toString();
    }
}

